package com.asmj.marketplace.jobs;
import java.math.BigDecimal; import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="job_postings")
public class JobPosting {
 @Id private String id; private String employerProfileId; private String employerUserId; private String organisationName; private String title; private String department; private String employmentType="FULL_TIME"; private String workMode="ONSITE"; private String description; private String responsibilities; private String qualifications; private String skills; private String experience; private BigDecimal salaryMin; private BigDecimal salaryMax; private String salaryPeriod="YEARLY"; private String city; private String state; private String pinCode; private String applicationEmail; private String status="PENDING"; private String adminNote; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now(); private Instant closingDate;
 public String getId(){return id;} public void setId(String v){id=v;} public String getEmployerProfileId(){return employerProfileId;} public void setEmployerProfileId(String v){employerProfileId=v;} public String getEmployerUserId(){return employerUserId;} public void setEmployerUserId(String v){employerUserId=v;} public String getOrganisationName(){return organisationName;} public void setOrganisationName(String v){organisationName=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getEmploymentType(){return employmentType;} public void setEmploymentType(String v){employmentType=v;} public String getWorkMode(){return workMode;} public void setWorkMode(String v){workMode=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getResponsibilities(){return responsibilities;} public void setResponsibilities(String v){responsibilities=v;} public String getQualifications(){return qualifications;} public void setQualifications(String v){qualifications=v;} public String getSkills(){return skills;} public void setSkills(String v){skills=v;} public String getExperience(){return experience;} public void setExperience(String v){experience=v;} public BigDecimal getSalaryMin(){return salaryMin;} public void setSalaryMin(BigDecimal v){salaryMin=v;} public BigDecimal getSalaryMax(){return salaryMax;} public void setSalaryMax(BigDecimal v){salaryMax=v;} public String getSalaryPeriod(){return salaryPeriod;} public void setSalaryPeriod(String v){salaryPeriod=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getState(){return state;} public void setState(String v){state=v;} public String getPinCode(){return pinCode;} public void setPinCode(String v){pinCode=v;} public String getApplicationEmail(){return applicationEmail;} public void setApplicationEmail(String v){applicationEmail=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} public Instant getClosingDate(){return closingDate;} public void setClosingDate(Instant v){closingDate=v;}
}
